// Isolation test (OS-12) — construct InvalidationScope with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import type { Currency, Unit } from "../src/catalog/index.js";
import { LineageReader } from "../src/facts/index.js";
import { InvalidationScope } from "../src/lineage/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";
import { factWorld, never } from "./support/fact-world.js";

const u = "u1" as Unit;
const [c0, c1] = ["c0", "c1"] as unknown as readonly [Currency, Currency];

describe("InvalidationScope in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new InvalidationScope({} as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new InvalidationScope({ lineage: {} as never })).toThrow();
    expect(() => new InvalidationScope({ lineage: { derivedFrom: () => [] } as never })).toThrow();
  });

  it("of answers differently when lineage differs", () => {
    const w = factWorld({ currencies: ["c0", "c1"], invalidations: never });
    const k0 = w.commitAt(u, c0);
    w.drawAt(u, c1);
    const h = w.record.noise();
    const a = new InvalidationScope({ lineage: new LineageReader({ record: w.record }) }).of(k0.at).compute(h);
    const b = new InvalidationScope({ lineage: new LineageReader({ record: inMemoryRecord() }) }).of(k0.at).compute(h);
    expect(a).not.toEqual(b);
  });
});
